 const [analysisId,setAnalysisId]=useState(""); const [queue,setQueue]=useState<QueueItem[]>([]); const [selected,setSelected]=useState<QueueItem|null>(null); const [review,setReview]=useState<Bundle|null>(null);
 const [loadedAnalysisId,setLoadedAnalysisId]=useState(""); const analysisIdRef=useRef(analysisId); const selectedVariantRef=useRef(selected?.variant_id??""); const queueRequest=useRef(0); const detailRequest=useRef(0); const governanceRequest=useRef(0); const familyRequest=useRef(0); analysisIdRef.current=analysisId; selectedVariantRef.current=selected?.variant_id??"";
 const [sessionRole,setSessionRole]=useState<string|null>(null); const [roleResolved,setRoleResolved]=useState(false); const canWriteCaseData=canGenerateOrEvaluateReports(sessionRole); const canAuthorizeClinical=canFinalizeClinicalReports(sessionRole);
 const [status,setStatus]=useState(""); const [classification,setClassification]=useState(""); const [reportability,setReportability]=useState(""); const [loading,setLoading]=useState(false); const [message,setMessage]=useState(""); const [reason,setReason]=useState(""); const [quality,setQuality]=useState<any>(null); const [qcMetricName,setQcMetricName]=useState(""); const [qcMetricValue,setQcMetricValue]=useState(""); const [qcMetricUnit,setQcMetricUnit]=useState(""); const [qcSource,setQcSource]=useState("LAB_QC"); const [qcSourceVersion,setQcSourceVersion]=useState(""); const [qcReviewerNote,setQcReviewerNote]=useState(""); const [qcSaving,setQcSaving]=useState(false);
 const [criterionReasons,setCriterionReasons]=useState<Record<string,string>>({}); const [criterionStrengths,setCriterionStrengths]=useState<Record<string,string>>({}); const [criterionEvidence,setCriterionEvidence]=useState<Record<string,string[]>>({});
 const [hpo,setHpo]=useState(""); const [hpoLabel,setHpoLabel]=useState(""); const [hpoStatus,setHpoStatus]=useState("PRESENT"); const [addingHpo,setAddingHpo]=useState(false);
 const [pedigreeMembers,setPedigreeMembers]=useState<PedigreeMember[]>([]); const [pedigreeRelationships,setPedigreeRelationships]=useState<any[]>([]); const [segregation,setSegregation]=useState<Segregation[]>([]); const [inheritanceAssessments,setInheritanceAssessments]=useState<any[]>([]);
 const [memberId,setMemberId]=useState(""); const [memberRelation,setMemberRelation]=useState("sibling"); const [memberSex,setMemberSex]=useState(""); const [memberAffected,setMemberAffected]=useState("UNKNOWN"); const [memberProband,setMemberProband]=useState(false); const [memberSampled,setMemberSampled]=useState(false);
 const [parentId,setParentId]=useState(""); const [childId,setChildId]=useState("");
 const [segMember,setSegMember]=useState(""); const [segGenotype,setSegGenotype]=useState(""); const [segZygosity,setSegZygosity]=useState(""); const [segPhase,setSegPhase]=useState(""); const [segPhenotype,setSegPhenotype]=useState(""); const [inheritanceModels,setInheritanceModels]=useState<string[]>(["AD","AR","X_LINKED","MITOCHONDRIAL","DE_NOVO"]); const [inheritanceNote,setInheritanceNote]=useState("");
 const [governance,setGovernance]=useState<any>(null); const [confirmationRequired,setConfirmationRequired]=useState(false); const [confirmationStatus,setConfirmationStatus]=useState("PENDING"); const [confirmationMethod,setConfirmationMethod]=useState(""); const [confirmationResult,setConfirmationResult]=useState(""); const [confirmationLab,setConfirmationLab]=useState(""); const [confirmationAccession,setConfirmationAccession]=useState(""); const [confirmationNotes,setConfirmationNotes]=useState(""); const [followAction,setFollowAction]=useState(""); const [followStatus,setFollowStatus]=useState("PLANNED"); const [followDue,setFollowDue]=useState(""); const [followNotes,setFollowNotes]=useState(""); const [secondaryPolicy,setSecondaryPolicy]=useState("LAB_SECONDARY_FINDINGS"); const [secondaryVersion,setSecondaryVersion]=useState("1.0"); const [secondaryConsent,setSecondaryConsent]=useState("NOT_DOCUMENTED"); const [secondaryDisposition,setSecondaryDisposition]=useState("REVIEW"); const [secondaryStatus,setSecondaryStatus]=useState("DRAFT"); const [secondaryRationale,setSecondaryRationale]=useState("");
 useEffect(()=>{let active=true;apiFetch("/auth/session").then(session=>{if(active)setSessionRole(typeof session?.role==="string"?session.role:null)}).catch(()=>{if(active)setSessionRole(null)}).finally(()=>{if(active)setRoleResolved(true)});return()=>{active=false}},[]);
 useEffect(()=>{
   let cancelled=false;
   const bootstrapAnalysis=async()=>{
    const caseId=window.localStorage.getItem("siraloom.case_id")??"";
    const storedAnalysis=window.localStorage.getItem("siraloom.analysis_id")??"";
    try{
     if(caseId){
      const caseData=await apiFetch(`/cases/${caseId}`);
       if(cancelled||analysisIdRef.current)return;
      const availableAnalyses=Array.isArray(caseData?.analyses)?caseData.analyses:[];
      const requestedAnalysis=availableAnalyses.find((item:any)=>String(item.analysis_id)===storedAnalysis)??availableAnalyses[0]??null;
      if(requestedAnalysis?.analysis_id){
       const id=String(requestedAnalysis.analysis_id);
       setAnalysisId(id);
       window.localStorage.setItem("siraloom.analysis_id",id);
      }else{
       setAnalysisId("");
       window.localStorage.removeItem("siraloom.analysis_id");
      }
      return;
     }
     }catch(e){
      if(!cancelled)setMessage(e instanceof Error?e.message:t("review.resolveCaseFailed"));
    }
    if(!cancelled&&!analysisIdRef.current&&storedAnalysis)setAnalysisId(storedAnalysis);
   };
   bootstrapAnalysis();
   return ()=>{cancelled=true};
  },[]);
 const loadQueue=async()=>{const requestedId=analysisId;const request=++queueRequest.current;if(!requestedId){setMessage(t("review.noAnalysisFirst"));return;}setLoading(true);setMessage("");try{const q=new URLSearchParams();if(status)q.set("status",status);if(classification)q.set("classification",classification);if(reportability)q.set("reportability",reportability);const d=await apiFetch(`/analyses/${requestedId}/review-queue?${q}`);if(request!==queueRequest.current||analysisIdRef.current!==requestedId)return;const items=Array.isArray(d.items)?d.items:[];setQueue(items);setSelected(current=>items.find((item:QueueItem)=>item.variant_id===current?.variant_id)??items[0]??null);setLoadedAnalysisId(requestedId);}catch(e){if(request===queueRequest.current&&analysisIdRef.current===requestedId)setMessage(e instanceof Error?e.message:t("review.loadQueueFailed"))}finally{if(request===queueRequest.current&&analysisIdRef.current===requestedId)setLoading(false)}};
 useEffect(()=>{setLoadedAnalysisId("");setQueue([]);setSelected(null);setReview(null);setGovernance(null);setQuality(null);setPedigreeMembers([]);setPedigreeRelationships([]);setSegregation([]);setInheritanceAssessments([]);setReason("");setCriterionReasons({});setCriterionStrengths({});setCriterionEvidence({});setHpo("");setHpoLabel("");setHpoStatus("PRESENT");setMemberId("");setMemberRelation("sibling");setMemberSex("");setMemberAffected("UNKNOWN");setMemberProband(false);setMemberSampled(false);setParentId("");setChildId("");setSegMember("");setSegGenotype("");setSegZygosity("");setSegPhase("");setSegPhenotype("");setInheritanceModels(["AD","AR","X_LINKED","MITOCHONDRIAL","DE_NOVO"]);setInheritanceNote("");setConfirmationRequired(false);setConfirmationStatus("PENDING");setConfirmationMethod("");setConfirmationResult("");setConfirmationLab("");setConfirmationAccession("");setConfirmationNotes("");setFollowAction("");setFollowStatus("PLANNED");setFollowDue("");setFollowNotes("");setSecondaryPolicy("LAB_SECONDARY_FINDINGS");setSecondaryVersion("1.0");setSecondaryConsent("NOT_DOCUMENTED");setSecondaryDisposition("REVIEW");setSecondaryStatus("DRAFT");setSecondaryRationale("");setMessage("");if(analysisId)loadQueue();else{queueRequest.current+=1;setLoading(false)}},[analysisId]);
 const loadReview=async()=>{if(!selected)return;const requestedId=analysisId;const variantId=selected.variant_id;const request=++detailRequest.current;try{const bundle=await apiFetch(`/analyses/${requestedId}/variants/${variantId}/review`);if(request!==detailRequest.current||analysisIdRef.current!==requestedId||selectedVariantRef.current!==variantId)return;setReview(bundle);try{const qualityData=await apiFetch(`/analyses/${requestedId}/quality`);if(request===detailRequest.current&&analysisIdRef.current===requestedId&&selectedVariantRef.current===variantId)setQuality(qualityData);}catch(e){if(request===detailRequest.current&&analysisIdRef.current===requestedId&&selectedVariantRef.current===variantId)setMessage(e instanceof Error?e.message:t("review.loadClinicalFailed"))}}catch(e){if(request===detailRequest.current&&analysisIdRef.current===requestedId&&selectedVariantRef.current===variantId)setMessage(e instanceof Error?e.message:t("review.loadClinicalFailed"))}};
 const loadGovernance=async()=>{if(!selected)return;const requestedId=analysisId;const variantId=selected.variant_id;const request=++governanceRequest.current;try{const d=await apiFetch(`/analyses/${requestedId}/variants/${variantId}/clinical-governance`);if(request!==governanceRequest.current||analysisIdRef.current!==requestedId||selectedVariantRef.current!==variantId)return;setGovernance(d);const c=d.confirmation;if(c){setConfirmationRequired(!!c.required);setConfirmationStatus(c.status||"PENDING");setConfirmationMethod(c.method||"");setConfirmationResult(c.result||"");setConfirmationLab(c.laboratory||"");setConfirmationAccession(c.accession||"");setConfirmationNotes(c.notes||"")} }catch(e){if(request===governanceRequest.current&&analysisIdRef.current===requestedId&&selectedVariantRef.current===variantId)setMessage(e instanceof Error?e.message:"Unable to load clinical governance.")}};
 useEffect(()=>{detailRequest.current+=1;governanceRequest.current+=1;familyRequest.current+=1;setReview(null);setGovernance(null);setQuality(null);setSegregation([]);setInheritanceAssessments([]);setReason("");setCriterionReasons({});setCriterionStrengths({});setCriterionEvidence({});setConfirmationRequired(false);setConfirmationStatus("PENDING");setConfirmationMethod("");setConfirmationResult("");setConfirmationLab("");setConfirmationAccession("");setConfirmationNotes("");setFollowAction("");setFollowStatus("PLANNED");setFollowDue("");setFollowNotes("");setSecondaryRationale("");if(selected){loadReview();loadGovernance()}},[selected,analysisId]);
 const loadFamily=async()=>{if(!review)return;const requestedId=analysisId;const variantId=review.variant_id;const caseId=review.case_id;const request=++familyRequest.current;try{const [p,s]=await Promise.all([apiFetch(`/cases/${caseId}/pedigree`),apiFetch(`/analyses/${requestedId}/variants/${variantId}/segregation`)]);if(request!==familyRequest.current||analysisIdRef.current!==requestedId||selectedVariantRef.current!==variantId)return;setPedigreeMembers(p.members??[]);setPedigreeRelationships(p.relationships??[]);setSegregation(s.observations??[]);setInheritanceAssessments(s.assessments??[]);}catch(e){if(request===familyRequest.current&&analysisIdRef.current===requestedId&&selectedVariantRef.current===variantId)setMessage(e instanceof Error?e.message:"Unable to load pedigree context.")}};
 useEffect(()=>{if(review)loadFamily()},[review?.case_id,review?.variant_id,analysisId]);
 const evidence=useMemo(()=>review?.variant_context?.gene_disease?.concat(review.variant_context.phenotype_evidence??[],review.variant_context.literature??[],review.variant_context.functional_computational??[],review.variant_context.segregation??[])??[],[review]);
 const reload=async()=>{await loadReview();await loadGovernance();await loadQueue()};
 const startReview=async()=>{if(!selected)return;try{await apiFetch(`/analyses/${analysisId}/variants/${selected.variant_id}/review/start`,{method:"POST"});await reload();setMessage(t("review.startMessage"))}catch(e){setMessage(e instanceof Error?e.message:"Unable to start review.")}};
 const saveCriterion=async(c:any,decision:"ACCEPT"|"MODIFY"|"REJECT")=>{if(!selected)return;const r=criterionReasons[c.criterion]?.trim();if(!r){setMessage(`Add a rationale for ${c.criterion}.`);return;}try{await apiFetch(`/analyses/${analysisId}/variants/${selected.variant_id}/acmg/${c.criterion}/review`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({decision,strength:criterionStrengths[c.criterion]||c.reviewed_assessment?.strength||c.automated_assessment?.strength||"SUPPORTING",reason:r,evidence_ids:criterionEvidence[c.criterion]??[],expected_version:Number(c.review_version??0)})});await reload();setMessage(`${c.criterion} ${decision.toLowerCase()}d.`)}catch(e){setMessage(e instanceof Error?e.message:"Criterion review failed.")}};
 const classificationAction=async(action:"approve"|"more-evidence")=>{if(!selected||!review||!reason.trim()){setMessage("Document a decision reason first.");return;}try{await apiFetch(`/analyses/${analysisId}/variants/${selected.variant_id}/review/${action}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({expected_version:Number(review.classification?.review_version??0),reason:reason.trim()})});setReason("");await reload();setMessage(action==="approve"?"Classification approved and versioned.":"Additional evidence requested.")}catch(e){setMessage(e instanceof Error?e.message:"Review action failed.")}};
 const addMember=async()=>{if(!canWriteCaseData||!review||!memberId.trim())return;try{await apiFetch(`/cases/${review.case_id}/pedigree/members`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({member_identifier:memberId.trim(),relationship_to_proband:memberRelation||null,sex:memberSex||null,affected_status:memberAffected,is_proband:memberProband,sampled:memberSampled})});setMemberId("");setMemberProband(false);await loadFamily();setMessage(t("review.pedigreeMemberAdded"))}catch(e){setMessage(e instanceof Error?e.message:"Unable to add pedigree member.")}};
 const addRelationship=async()=>{if(!canWriteCaseData||!review||!parentId||!childId)return;try{await apiFetch(`/cases/${review.case_id}/pedigree/relationships`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({parent_member_id:parentId,child_member_id:childId})});setParentId("");setChildId("");await loadFamily();setMessage(t("review.pedigreeRelationshipAdded"))}catch(e){setMessage(e instanceof Error?e.message:"Unable to add pedigree relationship.")}};
 const addSegregation=async()=>{if(!canWriteCaseData||!selected||!segMember)return;try{await apiFetch(`/analyses/${analysisId}/variants/${selected.variant_id}/segregation`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({pedigree_member_id:segMember,genotype:segGenotype||null,zygosity:segZygosity||null,phase:segPhase||null,phenotype_status:segPhenotype||null,source:"HUMAN_REVIEW"})});setSegGenotype("");setSegZygosity("");setSegPhase("");await loadFamily();setMessage(t("review.segregationRecorded"))}catch(e){setMessage(e instanceof Error?e.message:"Unable to save segregation observation.")}};
